  @JavascriptInterface public void openSettings(String action){runOnUiThread(()->{try{startActivity(new Intent(action));}catch(Exception e){startActivity(new Intent(Settings.ACTION_SETTINGS));}});}
  @JavascriptInterface public void repairPlan(){runOnUiThread(()->web.evaluateJavascript("toast('Maak eerst een backup. Daarna begeleidt SafeScan je per herstelactie.')",null));}
