 private byte[] createDetailedPdf(String text)throws Exception{ReportWriter w=new ReportWriter();w.cover();String[] lines=text.split("\n",-1);for(int i=0;i<lines.length;i++){String line=lines[i];if(line.startsWith("SECTION|")){w.section(line.substring(8));}else if(line.startsWith("KV|")){String[]p=line.split("\\|",3);w.keyValue(p.length>1?p[1]:"",p.length>2?p[2]:"");}else if(line.startsWith("FINDING|")){String[]p=line.split("\\|",5);String detail=i+1<lines.length&&lines[i+1].startsWith("DETAIL|")?lines[++i].substring(7):"";String advice=i+1<lines.length&&lines[i+1].startsWith("ADVICE|")?lines[++i].substring(7):"";w.finding(p.length>1?p[1]:"neutral",p.length>2?p[2]:"",p.length>3?p[3]:"Bevinding",detail,advice);}else if(line.startsWith("TEXT|")){w.paragraph(line.substring(5));}}w.section("Uitgebreide toestelgegevens");for(String info:deviceInfo().split("\n")){int at=info.indexOf(':');if(at>0)w.keyValue(info.substring(0,at),info.substring(at+1).trim());else w.paragraph(info);}w.section("Methodiek en beperkingen");w.paragraph("SafeScan voert lokale triage uit op zichtbare Android-instellingen, pakketmetadata, boot-eigenschappen en beveiligingsconfiguratie. De resultaten zijn momentopnamen en moeten in context worden beoordeeld.");w.paragraph("Geen enkele gewone Android-app kan Pegasus, SS7-misbruik of alle geavanceerde implantaten definitief aantonen of uitsluiten. Een lage risicoscore is geen bewijs dat het toestel schoon is. Bij concrete verdenking is forensische acquisitie met AndroidQF/MVT of onderzoek door een specialist nodig.");return w.finish();}
 private class ReportWriter{final PdfDocument doc=new PdfDocument();final Paint navy=new Paint(1),violet=new Paint(1),white=new Paint(1),text=new Paint(1),muted=new Paint(1),bold=new Paint(1),panel=new Paint(1);PdfDocument.Page page;Canvas c;int y,pageNo;final Bitmap logo=BitmapFactory.decodeResource(getResources(),R.drawable.deus_group_safescan);ReportWriter(){navy.setColor(Color.rgb(7,16,25));violet.setColor(Color.rgb(116,44,255));white.setColor(Color.WHITE);text.setColor(Color.rgb(27,40,49));text.setTextSize(10);muted.setColor(Color.rgb(92,108,120));muted.setTextSize(9);bold.setColor(Color.rgb(20,31,40));bold.setTextSize(12);bold.setTypeface(Typeface.DEFAULT_BOLD);panel.setColor(Color.rgb(244,247,249));}void header(){pageNo++;page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,pageNo).create());c=page.getCanvas();c.drawColor(Color.WHITE);c.drawRect(0,0,595,82,navy);c.drawBitmap(logo,null,new RectF(28,10,90,72),null);Paint h=new Paint(white);h.setTextSize(19);h.setTypeface(Typeface.DEFAULT_BOLD);c.drawText("SafeScan",108,38,h);Paint s=new Paint(white);s.setTextSize(9);s.setColor(Color.rgb(190,201,212));c.drawText("UITGEBREID BEVEILIGINGSRAPPORT",108,58,s);c.drawRect(0,78,595,82,violet);y=108;}void closePage(){if(page!=null){c.drawText("DEUS_GROUP · SafeScan 1.5.0 · pagina "+pageNo,28,820,muted);doc.finishPage(page);page=null;}}void ensure(int need){if(page==null)header();if(y+need>795){closePage();header();}}void cover(){header();Paint t=new Paint(bold);t.setTextSize(25);t.setColor(Color.rgb(116,44,255));c.drawText("Beveiligingsrapport",28,y+24,t);y+=46;paragraph("Officieel lokaal gegenereerd rapport voor beveiligingstriage van dit Android-toestel.");Paint line=new Paint(violet);c.drawRoundRect(28,y,567,y+4,2,2,line);y+=22;}List<String>wrap(String value,int max){List<String>out=new ArrayList<>();String v=value==null?"":value.trim();if(v.isEmpty()){out.add("");return out;}while(v.length()>max){int cut=v.lastIndexOf(' ',max);if(cut<max/2)cut=max;out.add(v.substring(0,cut));v=v.substring(cut).trim();}out.add(v);return out;}void paragraph(String value){List<String>ls=wrap(value,96);ensure(ls.size()*14+8);for(String l:ls){c.drawText(l,28,y,text);y+=14;}y+=7;}void section(String name){ensure(42);y+=8;Paint p=new Paint(bold);p.setTextSize(15);p.setColor(Color.rgb(18,31,41));c.drawText(name,28,y,p);c.drawRect(28,y+7,567,y+10,violet);y+=30;}void keyValue(String key,String value){List<String>ls=wrap(value,70);ensure(Math.max(20,ls.size()*13+6));c.drawText(key,28,y,bold);int yy=y;c.drawText(ls.get(0),190,yy,text);for(int i=1;i<ls.size();i++){yy+=13;c.drawText(ls.get(i),190,yy,text);}y=Math.max(y+20,yy+17);}void finding(String level,String status,String title,String detail,String advice){List<String>d=wrap(detail,86),a=wrap(advice,86);int h=104+d.size()*13+a.size()*13;ensure(h+16);int color="high".equals(level)?Color.rgb(255,82,96):"warn".equals(level)?Color.rgb(246,163,42):"safe".equals(level)?Color.rgb(52,196,145):Color.rgb(125,140,155);panel.setColor(Color.rgb(244,247,249));c.drawRoundRect(28,y,567,y+h,9,9,panel);Paint bar=new Paint(1);bar.setColor(color);c.drawRoundRect(28,y,35,y+h,5,5,bar);Paint heading=new Paint(bold);heading.setColor(color);c.drawText(status.toUpperCase(Locale.ROOT),48,y+21,heading);Paint name=new Paint(bold);name.setTextSize(13);c.drawText(title,48,y+41,name);int yy=y+59;c.drawText("Vaststelling",48,yy,bold);yy+=15;for(String l:d){c.drawText(l,48,yy,text);yy+=13;}yy+=5;c.drawText("Aanbevolen actie",48,yy,bold);yy+=15;for(String l:a){c.drawText(l,48,yy,text);yy+=13;}y+=h+14;}byte[]finish()throws Exception{closePage();ByteArrayOutputStream out=new ByteArrayOutputStream();doc.writeTo(out);doc.close();return out.toByteArray();}}
 private byte[] createPdf(String text)throws Exception{String full=text+"\n\nTOESTELGEGEVENS\n"+deviceInfo();PdfDocument doc=new PdfDocument();Paint navy=new Paint(1),white=new Paint(1),violet=new Paint(1),body=new Paint(1),bold=new Paint(1),muted=new Paint(1),card=new Paint(1);navy.setColor(Color.rgb(7,16,25));white.setColor(Color.WHITE);white.setTextSize(21);white.setTypeface(Typeface.DEFAULT_BOLD);violet.setColor(Color.rgb(116,44,255));body.setColor(Color.rgb(30,44,54));body.setTextSize(10);bold.setColor(Color.rgb(20,34,44));bold.setTextSize(12);bold.setTypeface(Typeface.DEFAULT_BOLD);muted.setColor(Color.rgb(100,116,128));muted.setTextSize(9);card.setColor(Color.rgb(242,246,249));Bitmap logo=BitmapFactory.decodeResource(getResources(),R.drawable.deus_group_safescan);String[] lines=full.split("\n",-1);int pageNo=0,y=0;PdfDocument.Page page=null;Canvas c=null;for(int i=0;i<lines.length;i++){String line=lines[i];if(page==null||y>770){if(page!=null){c.drawText("DEUS_GROUP · SafeScan · pagina "+pageNo,32,820,muted);doc.finishPage(page);}pageNo++;page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,pageNo).create());c=page.getCanvas();c.drawColor(Color.WHITE);c.drawRect(0,0,595,92,navy);c.drawBitmap(logo,null,new RectF(28,13,94,79),null);c.drawText("SafeScan",112,43,white);Paint sub=new Paint(muted);sub.setColor(Color.rgb(185,196,208));sub.setTextSize(10);c.drawText("OFFICIEEL LOKAAL BEVEILIGINGSRAPPORT",112,65,sub);c.drawRect(0,88,595,92,violet);y=122;}if(line.equals("SafeScan beveiligingsrapport"))continue;if(line.equals("TOESTELGEGEVENS")){y+=8;c.drawText("TOESTELGEGEVENS",32,y,bold);c.drawRect(32,y+7,563,y+9,violet);y+=28;continue;}if(line.isEmpty()){y+=7;continue;}if(line.startsWith("[")){String detail=(i+1<lines.length)?lines[++i]:"";if(y>735){i-=2;y=999;continue;}int color=line.contains("Hoog risico")?Color.rgb(255,82,96):line.contains("Let op")?Color.rgb(246,163,42):line.contains("Veilig")?Color.rgb(52,196,145):Color.rgb(125,140,155);card.setColor(Color.rgb(244,247,249));c.drawRoundRect(28,y-17,567,y+43,8,8,card);Paint stripe=new Paint(1);stripe.setColor(color);c.drawRoundRect(28,y-17,34,y+43,4,4,stripe);Paint status=new Paint(bold);status.setColor(color);status.setTextSize(10);c.drawText(line,44,y,status);c.drawText(shortenPdf(detail,86),44,y+22,muted);y+=72;continue;}if(line.startsWith("Score:")){Paint score=new Paint(bold);score.setColor(Color.rgb(116,44,255));score.setTextSize(18);c.drawText(line,32,y,score);y+=25;continue;}c.drawText(shortenPdf(line,90),32,y,line.endsWith(":")?bold:body);y+=16;}if(page!=null){c.drawText("DEUS_GROUP · SafeScan · pagina "+pageNo,32,820,muted);doc.finishPage(page);}ByteArrayOutputStream out=new ByteArrayOutputStream();doc.writeTo(out);doc.close();return out.toByteArray();}
 private String shortenPdf(String s,int max){return s.length()>max?s.substring(0,max-1)+"…":s;}
 private String deviceInfo(){StatFs fs=new StatFs(Environment.getDataDirectory().getPath());long total=fs.getTotalBytes()/1073741824L,free=fs.getAvailableBytes()/1073741824L;ActivityManager.MemoryInfo mi=new ActivityManager.MemoryInfo();((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(mi);String androidId=Settings.Secure.getString(getContentResolver(),Settings.Secure.ANDROID_ID);String accounts="Door Android afgeschermd voor deze app";try{Account[] found=AccountManager.get(this).getAccountsByType("com.google");if(found.length>0){List<String> names=new ArrayList<>();for(Account a:found)names.add(a.name);accounts=android.text.TextUtils.join(", ",names);}}catch(Exception ignored){}TelephonyManager tm=(TelephonyManager)getSystemService(TELEPHONY_SERVICE);String operator="",simOperator="",country="",phoneType="Onbekend",networkType="Onbekend";try{operator=tm.getNetworkOperatorName();simOperator=tm.getSimOperatorName();country=tm.getNetworkCountryIso();phoneType=phoneTypeName(tm.getPhoneType());networkType=networkTypeName(tm.getDataNetworkType());}catch(Exception ignored){}return "Rapportbestand: "+reportFileName()+"\nAndroid-ID: "+androidId+"\nIMEI/MEID: Afgeschermd door Android voor niet-systeemapps\nIMSI: Afgeschermd door Android voor niet-systeemapps\nSimserienummer/ICCID: Afgeschermd door Android voor niet-systeemapps\nTelefoonnummer/MSISDN: Niet betrouwbaar beschikbaar zonder providerrechten\nFabrikant: "+Build.MANUFACTURER+"\nMerk: "+Build.BRAND+"\nModel: "+Build.MODEL+"\nProduct/apparaat: "+Build.PRODUCT+" / "+Build.DEVICE+"\nAndroid: "+Build.VERSION.RELEASE+" (API "+Build.VERSION.SDK_INT+")\nBeveiligingspatch: "+Build.VERSION.SECURITY_PATCH+"\nBuild-ID: "+Build.DISPLAY+"\nBuild fingerprint: "+Build.FINGERPRINT+"\nBootloader-versie: "+Build.BOOTLOADER+"\nBaseband/radio: "+Build.getRadioVersion()+"\nHardware/board: "+Build.HARDWARE+" / "+Build.BOARD+"\nProcessor-ABI: "+android.text.TextUtils.join(", ",Build.SUPPORTED_ABIS)+"\nNetwerkoperator: "+operator+"\nSimoperator: "+simOperator+"\nNetwerkland: "+country+"\nTelefoontype: "+phoneType+"\nMobiel datanetwerk: "+networkType+"\nSimstatus: "+tm.getSimState()+"\nOpslag: "+free+" GB vrij van "+total+" GB\nWerkgeheugen: "+(mi.totalMem/1073741824L)+" GB\nUptime: "+(SystemClock.elapsedRealtime()/3600000L)+" uur\nTaal/regio: "+Locale.getDefault().toLanguageTag()+"\nTijdzone: "+TimeZone.getDefault().getID()+"\nGoogle-accounts: "+accounts+"\nVerified Boot: "+prop("ro.boot.verifiedbootstate")+"\nVBMeta-status: "+prop("ro.boot.vbmeta.device_state")+"\nFlash lock: "+prop("ro.boot.flash.locked")+"\nSELinux: "+prop("ro.boot.selinux");}
 private String reportFileName(){String id=Settings.Secure.getString(getContentResolver(),Settings.Secure.ANDROID_ID);if(id==null||id.length()<6)id="onbekend";else id=id.substring(Math.max(0,id.length()-6));String model=(Build.MANUFACTURER+"-"+Build.MODEL).replaceAll("[^A-Za-z0-9_-]+","-");return "SafeScan-"+model+"-"+id+"-"+new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date())+".pdf";}
