  String access=settingSecure(Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);if(access.contains("anydesk")){add(findings,"Externe bediening","Hoog risico","AnyDesk-bedieningsservice is actief.","high");high++;}else if(!access.isEmpty()&&!"null".equals(access)){add(findings,"Toegankelijkheidsdiensten","Let op",shorten(access),"warn");warn++;}else{add(findings,"Toegankelijkheidsdiensten","Veilig","Geen extra dienst actief.","safe");safe++;}
  DevicePolicyManager dpm=(DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE);List<ComponentName> admins=dpm.getActiveAdmins();if(admins!=null&&!admins.isEmpty()){StringBuilder names=new StringBuilder();for(ComponentName c:admins){if(names.length()>0)names.append(", ");names.append(label(c.getPackageName()));}add(findings,"Apparaatbeheerders","Let op",admins.size()+" actief: "+shorten(names.toString()),"warn");warn++;}else{add(findings,"Apparaatbeheerders","Veilig","Geen externe beheerder actief.","safe");safe++;}
