  String proxy=Settings.Global.getString(getContentResolver(),Settings.Global.HTTP_PROXY),vpn=settingSecure("always_on_vpn_app");if(proxy!=null&&!proxy.isEmpty()&&!"null".equals(proxy)){add(findings,"Netwerkproxy","Hoog risico","Onverwachte proxy: "+proxy,"high");high++;}else{add(findings,"Netwerkproxy","Veilig","Geen systeemproxy ingesteld.","safe");safe++;}if(vpn!=null&&!vpn.isEmpty()&&!"null".equals(vpn)){add(findings,"Altijd-actieve VPN","Let op",vpn,"warn");warn++;}
  int adb=Settings.Global.getInt(getContentResolver(),Settings.Global.ADB_ENABLED,0);String tcp=prop("service.adb.tcp.port");if(adb==1||(!tcp.isEmpty()&&!"-1".equals(tcp))){add(findings,"ADB-debugging","Let op","Debugging is actief"+(tcp.isEmpty()?"":" op poort "+tcp)+".","warn");warn++;}else{add(findings,"ADB-debugging","Veilig","ADB is niet actief.","safe");safe++;}
