 private void add(JSONArray a,String title,String status,String detail,String level)throws JSONException{JSONObject o=new JSONObject();o.put("title",title);o.put("status",status);o.put("detail",detail);o.put("level",level);a.put(o);}private String prop(String k){try{Process p=new ProcessBuilder("getprop",k).start();BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()));String s=r.readLine();return s==null?"":s.trim();}catch(Exception e){return"";}}private String run(String command){try{Process p=new ProcessBuilder(command).start();BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()));String s=r.readLine();return s==null?"":s.trim();}catch(Exception e){return"";}}private boolean file(String p){return new File(p).exists();}private boolean installed(String p){try{getPackageManager().getPackageInfo(p,0);return true;}catch(Exception e){return false;}}private boolean granted(String permission,String pkg){return getPackageManager().checkPermission(permission,pkg)==PackageManager.PERMISSION_GRANTED;}private boolean hasRequested(PackageInfo p,String permission){if(p.requestedPermissions==null)return false;for(String q:p.requestedPermissions)if(permission.equals(q))return true;return false;}private String label(String p){try{return String.valueOf(getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(p,0)));}catch(Exception e){return p;}}private List<String> componentLabels(String raw){LinkedHashSet<String> names=new LinkedHashSet<>();for(String item:raw.split(":")){String pkg=item.split("/",2)[0].trim();if(!pkg.isEmpty())names.add(label(pkg));}return new ArrayList<>(names);}private String settingSecure(String k){try{String v=Settings.Secure.getString(getContentResolver(),k);return v==null?"":v;}catch(Exception e){return"";}}private String shorten(String s){return s;}
