 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if((req==SAVE||req==SAVE_PDF||req==BACKUP)&&result==RESULT_OK&&data!=null)try{OutputStream o=getContentResolver().openOutputStream(data.getData());o.write(report);o.close();web.evaluateJavascript(req==BACKUP?"backupDone=true;toast('Backup veilig opgeslagen')":"toast('Rapport opgeslagen')",null);}catch(Exception ignored){}else if(req==RESTORE&&result==RESULT_OK&&data!=null)try{InputStream in=getContentResolver().openInputStream(data.getData());BufferedReader r=new BufferedReader(new InputStreamReader(in,"UTF-8"));StringBuilder s=new StringBuilder();String line;while((line=r.readLine())!=null)s.append(line).append('\n');r.close();new JSONObject(s.toString());web.evaluateJavascript("backupDone=true;toast('Backup gecontroleerd en geladen. Herstelacties blijven handmatig bevestigd.')",null);}catch(Exception ignored){web.evaluateJavascript("toast('Ongeldige of beschadigde SafeScan-backup')",null);}}
